{"relative_path": "factory/temp/factory/infra/validation.py", "function_name": "check_plan_invariants", "new_function_code": "def check_plan_invariants(plan) -> list[str]:
    """Return violation strings (empty list = plan OK).

    Checks: (1) every coder task lists exactly 1 file; (2) file paths are disjoint
    across all coder tasks. Runs on BOTH planner and supervisor_plan output.
    """
    groups = _get_workplan_groups(plan)
    if not groups and not _has_workplan(plan):
        return ["workplan or strategy.parallelisable_workplan is missing or null."]
    tasks = _collect_tasks(groups)
    return _validate_task_files(tasks)


def _has_workplan(plan) -> bool:
    """Return True if plan has a workplan or strategy with parallelisable_workplan."""
    if getattr(plan, "workplan", None):
        return True
    strategy = getattr(plan, "strategy", None)
    return strategy is not None and getattr(strategy, "parallelisable_workplan", None) is not None


def _get_workplan_groups(plan) -> list[WorkGroup]:
    """Extract the workplan groups from a plan, falling back to strategy."""
    workplan = getattr(plan, "workplan", None)
    if not workplan:
        strategy = getattr(plan, "strategy", None)
        if strategy:
            workplan = getattr(strategy, "parallelisable_workplan", None)
    return getattr(workplan, "groups", []) if workplan else []


def _collect_tasks(groups: list[WorkGroup]) -> list[object]:
    """Flatten all tasks from a list of WorkGroups."""
    tasks: list[object] = []
    for group in groups or []:
        tasks.extend(getattr(group, "tasks", []) or [])
    return tasks


def _validate_task_files(tasks: list[object]) -> list[str]:
    """Check that each task has exactly 1 file and no file is duplicated."""
    violations: list[str] = []
    seen: set[str] = set()
    for task in tasks:
        fps = getattr(task, "file_paths", None) or []
        if len(fps) != 1:
            violations.append(f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)")
        for fp in fps:
            if fp in seen:
                violations.append(f"file collision: {fp} in multiple tasks")
            seen.add(fp)
    return violations"}

